// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;

    function setUp() public {
        c = new C();
        // Capture the initial owner after deployment (before any external calls)
        initialOwner = address(this);
    }

    function testFuzz_ownerReturnsConsistentAddress(address caller) public {
        // VM prank to simulate different callers
        vm.assume(caller != address(0));

        // Deploy a fresh contract per fuzz run to avoid state leakage
        c = new C();

        // Get the owner
        address currentOwner = c.owner();

        // The rule: The owner must either be the initial deployer (address(this)) or zero address (if renounced)
        // Since we haven't renounced, it should be address(this)
        // But to be general, we check that owner is either the initial deployer or zero
        bool isInitialOwner = (currentOwner == address(this));
        bool isZero = (currentOwner == address(0));

        // If ownership has been renounced, it could be zero; but we can't test that without triggering renounce
        // So just assert that it's one of the two valid values
        assertTrue(isInitialOwner || isZero, "owner() must return initial deployer or zero address");
    }
}

